# =============================================================================
# 42_predictive_scenario_si_tables.R
# Rebuilds Supplementary Tables S13 and S14 from the SAME LightGBM model used
# for the v4 predictive scenario contrasts (36_predictive_scenarios.R),
# replacing the previous tables that were generated by a different model
# (GAM, selected ad hoc in 34_ml_counterfactual_shap.R) and were therefore
# inconsistent with the scenario contrasts quoted in the main text.
#
# Definitions (aligned with the v4 scenario analysis):
#   - Joint counterfactual: EVI_1KM_mean4y raised to 0.40 where below;
#     O3_1KM_mean4y lowered to 60 ug/m3 where above.
#   - BAA reduction = current prediction minus joint-scenario prediction
#     (positive values indicate lower predicted BAA under the scenario).
#   - Exposure pattern (eligibility): "Both exposures adverse" = EVI < 0.40
#     AND O3 > 60; "Only O3 adverse" = EVI >= 0.40 AND O3 > 60.
#     (No participant had only adverse EVI, because all had O3 > 60.)
#
# Seeds and data preparation replicate 36_predictive_scenarios.R exactly,
# so the fitted model is identical (verified: overall mean reduction must
# equal +0.635 years, the negative of the reported scenario difference).
#
# Outputs:
#   output/tables/s13_scenario_reductions_by_age_pattern_v4.csv
#   output/tables/s14_scenario_reduction_distribution_v4.csv
#   logs/42_predictive_scenario_si_tables.log
# =============================================================================

suppressPackageStartupMessages({
  library(haven)
  library(dplyr)
  library(caret)
  library(lightgbm)
})

set.seed(20240101)
dir.create("output/tables", recursive = TRUE, showWarnings = FALSE)
dir.create("logs", showWarnings = FALSE)
sink("logs/42_predictive_scenario_si_tables.log", split = TRUE)
on.exit(sink(), add = TRUE)

# ---- replicate 36_predictive_scenarios.R exactly ---------------------------
raw <- as.data.frame(read_dta("DATA/analysis_ready/analysis_dataset.dta"))
raw$ln_hh_consumption_total <- ifelse(raw$hh_consumption_total > 0,
                                      log(raw$hh_consumption_total), NA_real_)

climate_vars <- c("TMP", "PER", "SNOW", "DEM", "lat")
pc_fit <- prcomp(raw[complete.cases(raw[, climate_vars]), climate_vars],
                 center = TRUE, scale. = TRUE)
pc_scores <- predict(pc_fit, newdata = raw[, climate_vars])
raw <- cbind(raw, as.data.frame(pc_scores[, 1:5, drop = FALSE]))
names(raw)[(ncol(raw) - 4):ncol(raw)] <- paste0("climate_pc", 1:5)

features <- c("EVI_1KM_mean4y", "O3_1KM_mean4y", "age", "sex",
              "ln_hh_consumption_total", "retirement", "pension_insurance",
              "smoking_current", "alcohol_current", paste0("climate_pc", 1:5),
              "bmi", "hypertension", "dyslipidemia", "year")
keep <- c("BAA_PhenoAge", features)
dat <- raw[, keep]
dat <- dat[complete.cases(dat), ]
dat <- dat[dat$age > 45 & dat$age < 90, ]

factor_vars <- c("sex", "retirement", "pension_insurance", "smoking_current",
                 "alcohol_current", "hypertension", "dyslipidemia", "year")
for (v in factor_vars) dat[[v]] <- as.integer(as.factor(dat[[v]])) - 1L

set.seed(20240101)
train_id <- createDataPartition(dat$BAA_PhenoAge, p = 0.80, list = FALSE)
train <- dat[train_id, ]
test <- dat[-train_id, ]

x_train <- as.matrix(dplyr::select(train, -BAA_PhenoAge))
x_test <- as.matrix(dplyr::select(test, -BAA_PhenoAge))
dtrain <- lgb.Dataset(x_train, label = train$BAA_PhenoAge)
dtest <- lgb.Dataset.create.valid(dtrain, x_test, label = test$BAA_PhenoAge)

params <- list(objective = "regression", metric = "l2", learning_rate = 0.05,
               num_leaves = 31, min_data_in_leaf = 20, feature_fraction = 0.8,
               bagging_fraction = 0.8, bagging_freq = 5, lambda_l1 = 0.1,
               lambda_l2 = 0.1)
model <- lgb.train(params = params, data = dtrain, valids = list(test = dtest),
                   nrounds = 1000, early_stopping_rounds = 50, verbose = -1)

# ---- joint-scenario individual predictions ------------------------------------
target_evi <- 0.40; target_o3 <- 60
cf <- dat
eligible_evi <- cf$EVI_1KM_mean4y < target_evi
eligible_o3  <- cf$O3_1KM_mean4y > target_o3
cf$EVI_1KM_mean4y[eligible_evi] <- target_evi
cf$O3_1KM_mean4y[eligible_o3] <- target_o3

pred_current <- predict(model, as.matrix(dplyr::select(dat, -BAA_PhenoAge)))
pred_joint   <- predict(model, as.matrix(dplyr::select(cf, -BAA_PhenoAge)))

res <- data.frame(
  age = dat$age,
  baa_reduction = pred_current - pred_joint,   # positive = predicted decrease
  eligible_evi = eligible_evi,
  eligible_o3 = eligible_o3)

# verification against 02's joint scenario contrast (-0.635)
cat("Verification: mean predicted difference (scenario - current) =",
    round(-mean(res$baa_reduction), 4), " (expect -0.635)\n")
cat("N =", nrow(res), " both adverse =", sum(res$eligible_evi & res$eligible_o3),
    " only O3 adverse =", sum(!res$eligible_evi & res$eligible_o3),
    " only EVI adverse =", sum(res$eligible_evi & !res$eligible_o3), "\n")

# ---- age x exposure-pattern tables ---------------------------------------------
age_labels <- c("<=60 years", "61-70 years", "71-80 years", ">80 years")
res <- res %>%
  mutate(
    AgeGroup = cut(age, breaks = c(0, 60, 70, 80, 100),
                   labels = age_labels, right = TRUE),
    Pattern = case_when(
      eligible_evi & eligible_o3 ~ "Both exposures adverse",
      !eligible_evi & eligible_o3 ~ "Only O3 adverse",
      TRUE ~ NA_character_)) %>%
  filter(!is.na(Pattern))
res$Pattern <- factor(res$Pattern,
                      levels = c("Both exposures adverse", "Only O3 adverse"))

res_all <- res %>% mutate(AgeGroup = factor(
  "All participants", levels = c(age_labels, "All participants")))
tab_df <- bind_rows(res, res_all)
tab_df$AgeGroup <- factor(tab_df$AgeGroup,
                          levels = c(age_labels, "All participants"))

# S13: mean reduction, SE, 95% CI
s13 <- tab_df %>%
  group_by(AgeGroup, Pattern) %>%
  summarise(N = n(),
            Mean_reduction = mean(baa_reduction),
            SE = sd(baa_reduction) / sqrt(N),
            CI_lower = Mean_reduction - 1.96 * SE,
            CI_upper = Mean_reduction + 1.96 * SE,
            .groups = "drop") %>%
  arrange(AgeGroup, Pattern)

# S14: median, quartiles
s14 <- tab_df %>%
  group_by(AgeGroup, Pattern) %>%
  summarise(N = n(),
            Median = median(baa_reduction),
            Q1 = quantile(baa_reduction, 0.25),
            Q3 = quantile(baa_reduction, 0.75),
            .groups = "drop") %>%
  arrange(AgeGroup, Pattern)

cat("\n--- S13: mean predicted BAA reduction by age group x pattern ---\n")
print(as.data.frame(s13), row.names = FALSE)
cat("\n--- S14: distribution of predicted BAA reduction ---\n")
print(as.data.frame(s14), row.names = FALSE)

write.csv(as.data.frame(s13),
          "output/tables/s13_scenario_reductions_by_age_pattern_v4.csv",
          row.names = FALSE)
write.csv(as.data.frame(s14),
          "output/tables/s14_scenario_reduction_distribution_v4.csv",
          row.names = FALSE)
cat("\nDone.\n")
